pragma solidity ^0.4.15;

contract BalanceAccumulator {
    uint private total=0;

    function accumulate(uint amount) returns (bool){
        total += amount; // possible overflow

        // possible auditor assert
        // assert(total >= amount); 
    } 

    function accumulateSafe(uint amount) returns (bool){
        require(amount + total >= total);
        total += amount; 
    } 
}
